static Matriz menor(Matriz M,int fi,int co){

    int n=M.fil(),a=0;

    int[][] R=new int[n-1][n-1];

    for(int i=0;i<n;i++)

        if(i!=fi){

            int b=0;

            for(int j=0;j<n;j++)

                if(j!=co)
                    R[a][b++]=M.get(i,j);

            a++;
        }

    return new Matriz(R);
}
